export default config;

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --background: #0a0e17;
  --foreground: #e5e9f0;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-thumb {
  background: #2a3242;
  border-radius: 4px;
}

{
  "extends": "next/core-web-vitals"
}

// Shared domain types for the BMW PM Decision Workflow app.
// This is the contract every role builds against. Changing a shape here
// is a team-wide announcement, not a solo edit.

export type ComponentKey =
  | "exterior"
  | "interior"
  | "windows"
  | "steering"
  | "engine"
  | "battery";

export interface Vehicle {
  id: string;
  name: string; // e.g. "BMW 5 Series"
  generation: string; // e.g. "G60 -> successor"
  markets: string[]; // e.g. ["Europe", "China", "United States"]
}

export interface VehicleComponent {
  id: string;
  vehicleId: string;
  key: ComponentKey;
  label: string; // "Battery & Charging"
  hotspot: { xPct: number; yPct: number }; // position on the 360 viewer, 0-100
  workflowId: string | null; // null => "create new" affordance on landing page
}

// ---------- Workflow / pipeline ----------

export type WorkflowStatus =
  | "draft"
  | "analyzing"
  | "stakeholder_review"
  | "pm_review"
  | "approved"
  | "rejected"
  | "archived";

export type StageKey =
  | "ingest"
  | "enrich"
  | "extract"
  | "derive"
  | "score"
  | "stakeholder_review"
  | "pm_decision"
  | "deploy";

export type StageStatus = "pending" | "active" | "complete" | "blocked" | "skipped";

export interface Stage {
  key: StageKey;
  label: string;
  status: StageStatus;
  startedAt: string | null;
  completedAt: string | null;
  owner: "ai" | "pm" | "stakeholder";
}

export interface Workflow {
  id: string;
  vehicleId: string;
  componentId: string;
  market: string;
  status: WorkflowStatus;
  stages: Stage[];
  createdAt: string;
  updatedAt: string;
}

// ---------- Evidence chain: sources -> signals -> requirements ----------

export type DatasetType = "verbatim" | "equipment" | "sales" | "study" | "web";
export type ReliabilityTier = "first_party" | "official" | "review_site" | "forum";

export interface SourceRecord {
  id: string;
  workflowId: string;
  datasetType: DatasetType;
  reliability: ReliabilityTier;
  title: string;
  excerpt: string;
  url: string | null; // null for internal datasets
  retrievedAt: string;
}

export interface Signal {
  id: string;
  workflowId: string;
  theme: string;
  frequency: number;
  sentiment: "positive" | "negative" | "mixed" | "neutral";
  sampleVerbatims: string[];
  sourceIds: string[];
  contradicts: string[]; // other signal ids this one conflicts with
}

export type EvidenceLevel = "strong" | "moderate" | "weak";
export type RequirementCategory =
  | "comfort"
  | "space"
  | "usability"
  | "infotainment_digital"
  | "design_quality"
  | "driving_experience"
  | "range_charging"
  | "variants_packages";

export type RequirementStatus =
  | "proposed"
  | "approved"
  | "rejected"
  | "postponed"
  | "challenged";

export interface ScoreFactor {
  key: string; // "customer_impact" | "frequency" | ...
  label: string;
  weight: number; // 0-1, factors across a requirement sum to 1
  rawValue: number; // 0-100 input value before weighting
  rationale: string;
}

export interface Requirement {
  id: string;
  workflowId: string;
  title: string;
  description: string;
  category: RequirementCategory;
  status: RequirementStatus;
  evidenceLevel: EvidenceLevel;
  assumptions: string[];
  uncertainties: string[];
  linkedSignalIds: string[];
  linkedSourceIds: string[];
  scoreFactors: ScoreFactor[];
  score: number; // computed weighted score, 0-100
  effort: "low" | "medium" | "high";
  createdAt: string;
  updatedAt: string;
}

// ---------- Stakeholders ----------

export type StakeholderExpertise =
  | "engineering"
  | "sales"
  | "design"
  | "legal_regulatory"
  | "brand"
  | "procurement";

export interface Stakeholder {
  id: string;
  name: string;
  expertise: StakeholderExpertise;
  avatarColor: string;
}

export type ReviewDecision = "approve" | "reject" | "pending";

export interface StakeholderReview {
  id: string;
  workflowId: string;
  stakeholderId: string;
  requirementId: string | null; // null = review covers whole workflow
  decision: ReviewDecision;
  expertOpinion: string;
  submittedAt: string | null;
  aiContextSnapshot: string; // the AI summary shown to the stakeholder at submit time
}

// ---------- Audit log (append-only) ----------

export type ActorType = "ai" | "pm" | "stakeholder";

export interface Actor {
  type: ActorType;
  id: string;
  name: string;
  model?: string; // e.g. "claude-sonnet-5" when type === "ai"
}

export type AuditAction =
  | "workflow_created"
  | "stage_transition"
  | "signal_extracted"
  | "requirement_proposed"
  | "requirement_edited"
  | "requirement_approved"
  | "requirement_rejected"
  | "requirement_postponed"
  | "requirement_challenged"
  | "score_recomputed"
  | "stakeholder_review_submitted"
  | "ai_summary_generated"
  | "weights_adjusted";

export interface AuditLogEntry {
  id: string;
  workflowId: string;
  actor: Actor;
  action: AuditAction;
  targetType: "workflow" | "requirement" | "stage" | "review";
  targetId: string;
  oldValue: unknown;
  newValue: unknown;
  rationale: string;
  timestamp: string;
}

// ---------- AI summaries ----------

export interface AISummary {
  id: string;
  workflowId: string;
  type: "decision_trail" | "stakeholder_overview" | "limitations";
  content: string;
  basedOnLogIds: string[];
  generatedAt: string;
}

// In-memory data store for the hackathon v0.
// Swap-out point for Role A: replace this module's internals with a real
// DB (Postgres/Prisma or SQLite) while keeping the exported function
// signatures identical so nothing above this layer has to change.
//
// Survives Next.js dev-mode hot reload by hanging off globalThis.

import { nanoid } from "nanoid";
import type {
  Vehicle,
  VehicleComponent,
  Workflow,
  Requirement,
  Signal,
  SourceRecord,
  Stakeholder,
  StakeholderReview,
  AuditLogEntry,
  AISummary,
  Actor,
  AuditAction,
} from "./types";
import { buildSeed } from "./seed";

interface Store {
  vehicles: Vehicle[];
  components: VehicleComponent[];
  workflows: Workflow[];
  requirements: Requirement[];
  signals: Signal[];
  sources: SourceRecord[];
  stakeholders: Stakeholder[];
  reviews: StakeholderReview[];
  auditLog: AuditLogEntry[];
  aiSummaries: AISummary[];
}

const globalForStore = globalThis as unknown as { __ehlStore?: Store };

function freshStore(): Store {
  return buildSeed();
}

export const store: Store = globalForStore.__ehlStore ?? (globalForStore.__ehlStore = freshStore());

// ---------- append-only audit log ----------

export function logAction(entry: {
  workflowId: string;
  actor: Actor;
  action: AuditAction;
  targetType: AuditLogEntry["targetType"];
  targetId: string;
  oldValue: unknown;
  newValue: unknown;
  rationale: string;
}): AuditLogEntry {
  const full: AuditLogEntry = {
    id: `log_${nanoid(8)}`,
    timestamp: new Date().toISOString(),
    ...entry,
  };
  store.auditLog.push(full);
  return full;
}

export function getAuditLog(workflowId: string): AuditLogEntry[] {
  return store.auditLog
    .filter((l) => l.workflowId === workflowId)
    .sort((a, b) => a.timestamp.localeCompare(b.timestamp));
}

// ---------- vehicles / components ----------

export function listVehicles(): Vehicle[] {
  return store.vehicles;
}

export function listComponents(vehicleId: string): VehicleComponent[] {
  return store.components.filter((c) => c.vehicleId === vehicleId);
}

export function getComponent(componentId: string): VehicleComponent | undefined {
  return store.components.find((c) => c.id === componentId);
}

// ---------- workflows ----------

export function getWorkflow(workflowId: string): Workflow | undefined {
  return store.workflows.find((w) => w.id === workflowId);
}

export function getWorkflowByComponent(componentId: string): Workflow | undefined {
  const comp = getComponent(componentId);
  if (!comp?.workflowId) return undefined;
  return getWorkflow(comp.workflowId);
}

export function createWorkflow(componentId: string, market: string): Workflow {
  const comp = getComponent(componentId);
  if (!comp) throw new Error("component not found");
  const now = new Date().toISOString();
  const workflow: Workflow = {
    id: `wf_${nanoid(8)}`,
    vehicleId: comp.vehicleId,
    componentId,
    market,
    status: "draft",
    stages: [
      { key: "ingest", label: "Ingest datasets", status: "active", startedAt: now, completedAt: null, owner: "pm" },
      { key: "enrich", label: "Enrich with web knowledge", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
      { key: "extract", label: "Extract signals", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
      { key: "derive", label: "Derive requirements", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
      { key: "score", label: "Score & prioritize", status: "pending", startedAt: null, completedAt: null, owner: "ai" },
      { key: "stakeholder_review", label: "Stakeholder review", status: "pending", startedAt: null, completedAt: null, owner: "stakeholder" },
      { key: "pm_decision", label: "PM decision", status: "pending", startedAt: null, completedAt: null, owner: "pm" },
      { key: "deploy", label: "Move to deploy", status: "pending", startedAt: null, completedAt: null, owner: "pm" },
    ],
    createdAt: now,
    updatedAt: now,
  };
  store.workflows.push(workflow);
  comp.workflowId = workflow.id;

  logAction({
    workflowId: workflow.id,
    actor: { type: "pm", id: "pm_demo", name: "Product Manager" },
    action: "workflow_created",
    targetType: "workflow",
    targetId: workflow.id,
    oldValue: null,
    newValue: { componentId, market },
    rationale: `Started a new requirements workflow for ${comp.label} in ${market}.`,
  });

  return workflow;
}

export function updateStage(
  workflowId: string,
  stageKey: Workflow["stages"][number]["key"],
  status: Workflow["stages"][number]["status"],
  actor: Actor,
) {
  const wf = getWorkflow(workflowId);
  if (!wf) throw new Error("workflow not found");
  const stage = wf.stages.find((s) => s.key === stageKey);
  if (!stage) throw new Error("stage not found");
  const oldStatus = stage.status;
  stage.status = status;
  const now = new Date().toISOString();
  if (status === "active" && !stage.startedAt) stage.startedAt = now;
  if (status === "complete") stage.completedAt = now;
  wf.updatedAt = now;

  logAction({
    workflowId,
    actor,
    action: "stage_transition",
    targetType: "stage",
    targetId: stageKey,
    oldValue: oldStatus,
    newValue: status,
    rationale: `${stage.label}: ${oldStatus} -> ${status}`,
  });
}

// ---------- requirements ----------

export function listRequirements(workflowId: string): Requirement[] {
  return store.requirements
    .filter((r) => r.workflowId === workflowId)
    .sort((a, b) => b.score - a.score);
}

export function getRequirement(id: string): Requirement | undefined {
  return store.requirements.find((r) => r.id === id);
}

export function recomputeScore(req: Requirement): number {
  const totalWeight = req.scoreFactors.reduce((s, f) => s + f.weight, 0) || 1;
  const weighted = req.scoreFactors.reduce((s, f) => s + (f.rawValue * f.weight), 0);
  return Math.round((weighted / totalWeight) * 10) / 10;
}

export function updateRequirementStatus(
  id: string,
  status: Requirement["status"],
  actor: Actor,
  rationale: string,
): Requirement {
  const req = getRequirement(id);
  if (!req) throw new Error("requirement not found");
  const oldStatus = req.status;
  req.status = status;
  req.updatedAt = new Date().toISOString();

  const actionMap: Record<Requirement["status"], AuditAction> = {
    proposed: "requirement_edited",
    approved: "requirement_approved",
    rejected: "requirement_rejected",
    postponed: "requirement_postponed",
    challenged: "requirement_challenged",
  };

  logAction({
    workflowId: req.workflowId,
    actor,
    action: actionMap[status],
    targetType: "requirement",
    targetId: req.id,
    oldValue: oldStatus,
    newValue: status,
    rationale,
  });

  return req;
}

export function updateWeights(
  requirementId: string,
  weights: Record<string, number>,
  actor: Actor,
): Requirement {
  const req = getRequirement(requirementId);
  if (!req) throw new Error("requirement not found");
  const oldScore = req.score;
  req.scoreFactors = req.scoreFactors.map((f) => ({
    ...f,
    weight: weights[f.key] ?? f.weight,
  }));
  req.score = recomputeScore(req);
  req.updatedAt = new Date().toISOString();

  logAction({
    workflowId: req.workflowId,
    actor,
    action: "weights_adjusted",
    targetType: "requirement",
    targetId: req.id,
    oldValue: { score: oldScore },
    newValue: { score: req.score, weights },
    rationale: "PM adjusted scoring factor weights.",
  });

  return req;
}

// ---------- signals / sources ----------

export function listSignals(workflowId: string): Signal[] {
  return store.signals.filter((s) => s.workflowId === workflowId);
}

export function listSources(workflowId: string): SourceRecord[] {
  return store.sources.filter((s) => s.workflowId === workflowId);
}

export function getSourcesByIds(ids: string[]): SourceRecord[] {
  return store.sources.filter((s) => ids.includes(s.id));
}

// ---------- stakeholders / reviews ----------

export function listStakeholders(): Stakeholder[] {
  return store.stakeholders;
}

export function getStakeholder(id: string): Stakeholder | undefined {
  return store.stakeholders.find((s) => s.id === id);
}

export function listReviews(workflowId: string): StakeholderReview[] {
  return store.reviews.filter((r) => r.workflowId === workflowId);
}

export function submitReview(
  reviewId: string,
  decision: StakeholderReview["decision"],
  expertOpinion: string,
): StakeholderReview {
  const review = store.reviews.find((r) => r.id === reviewId);
  if (!review) throw new Error("review not found");
  review.decision = decision;
  review.expertOpinion = expertOpinion;
  review.submittedAt = new Date().toISOString();

  const stakeholder = getStakeholder(review.stakeholderId);

  logAction({
    workflowId: review.workflowId,
    actor: { type: "stakeholder", id: review.stakeholderId, name: stakeholder?.name ?? "Stakeholder" },
    action: "stakeholder_review_submitted",
    targetType: "review",
    targetId: review.id,
    oldValue: { decision: "pending" },
    newValue: { decision, expertOpinion },
    rationale: expertOpinion,
  });

  return review;
}

// ---------- AI summaries ----------

export function listAISummaries(workflowId: string): AISummary[] {
  return store.aiSummaries.filter((s) => s.workflowId === workflowId);
}

export function addAISummary(summary: Omit<AISummary, "id" | "generatedAt">): AISummary {
  const full: AISummary = {
    ...summary,
    id: `aisum_${nanoid(8)}`,
    generatedAt: new Date().toISOString(),
  };
  store.aiSummaries.push(full);

  logAction({
    workflowId: summary.workflowId,
    actor: { type: "ai", id: "ai_engine", name: "Requirements Copilot", model: "claude-sonnet-5" },
    action: "ai_summary_generated",
    targetType: "workflow",
    targetId: summary.workflowId,
    oldValue: null,
    newValue: { type: summary.type },
    rationale: "Regenerated summary from latest audit log entries.",
  });

  return full;
}

// AI layer. Every function here is a MOCK that returns deterministic,
// template-based output so the rest of the app works end-to-end without an
// API key. Role B's job is to replace each function body with a real call
// to the Claude API, keeping the same input/output shape.
//
// Suggested real implementation: Anthropic SDK, model "claude-sonnet-5",
// with the relevant audit log entries / source excerpts passed in the
// prompt as structured context, and the response constrained to the
// same return shape (use tool-use / structured output for that).

import type { AuditLogEntry, Requirement, Signal, SourceRecord, StakeholderReview } from "./types";

export interface DecisionTrailInput {
  requirement: Requirement;
  relatedLogs: AuditLogEntry[];
}

/**
 * MOCK. Replace with: Claude call that reads relatedLogs and produces a
 * narrative of what was asked, what was proposed, what the PM pushed back
 * on, and how the proposal changed as a result.
 */
export function summarizeDecisionTrail(input: DecisionTrailInput): string {
  const { requirement, relatedLogs } = input;
  const challenges = relatedLogs.filter((l) => l.action === "requirement_challenged");
  if (challenges.length === 0) {
    return `No PM challenges yet on "${requirement.title}". Proposed with ${requirement.evidenceLevel} evidence from ${requirement.linkedSourceIds.length} source(s).`;
  }
  const latest = challenges[challenges.length - 1];
  return `PM challenged "${requirement.title}": "${latest.rationale}". The requirement was revised in response — see the audit log for the exact before/after.`;
}

export interface StakeholderOverviewInput {
  reviews: StakeholderReview[];
}

/**
 * MOCK. Replace with: Claude call that reads all reviews for a requirement
 * (or workflow) and produces a short synthesis of where reviewers agree,
 * disagree, and why — the "AI overview of who says what" from the brief.
 */
export function summarizeStakeholderReviews(input: StakeholderOverviewInput): string {
  const { reviews } = input;
  const submitted = reviews.filter((r) => r.decision !== "pending");
  const approvals = submitted.filter((r) => r.decision === "approve").length;
  const rejections = submitted.filter((r) => r.decision === "reject").length;
  const pending = reviews.length - submitted.length;
  if (submitted.length === 0) return "No stakeholder reviews submitted yet.";
  return `${approvals} approve, ${rejections} reject, ${pending} pending. ${
    rejections > 0
      ? `Rejection rationale: "${submitted.find((r) => r.decision === "reject")?.expertOpinion}"`
      : "No objections raised."
  }`;
}

/**
 * MOCK. Replace with: Claude call that re-evaluates a requirement's score
 * or rationale given the PM's specific argument, and states explicitly
 * whether the challenge changed the result (per US-6.3).
 */
export function reassessChallenge(requirement: Requirement, pmArgument: string): {
  changed: boolean;
  explanation: string;
} {
  const mentionsEvidence = /evidence|source|data|proof/i.test(pmArgument);
  return {
    changed: mentionsEvidence,
    explanation: mentionsEvidence
      ? `Re-assessed "${requirement.title}" against your argument. Found additional/clarified evidence grounds — adjusting evidence level and rationale accordingly.`
      : `Re-assessed "${requirement.title}" against your argument. The existing evidence base already accounts for this; score and rationale unchanged, but your objection is logged against the requirement for the audit trail.`,
  };
}

export interface ClusterInput {
  verbatims: { id: string; text: string }[];
}

/**
 * MOCK. Replace with: Claude call (or embeddings + clustering) that groups
 * verbatims into themes. Returns partial Signal objects; caller assigns ids.
 */
export function extractSignals(input: ClusterInput): Pick<Signal, "theme" | "frequency" | "sentiment" | "sampleVerbatims">[] {
  return [
    {
      theme: "Needs manual clustering review — mock extractor",
      frequency: input.verbatims.length,
      sentiment: "mixed",
      sampleVerbatims: input.verbatims.slice(0, 3).map((v) => v.text),
    },
  ];
}

export interface DeriveInput {
  signal: Signal;
  sources: SourceRecord[];
}

/**
 * MOCK. Replace with: Claude call that turns a signal + its sources into a
 * draft Requirement (title, description, category, evidence level,
 * assumptions, uncertainties) per US-3.1.
 */
export function deriveRequirement(input: DeriveInput): Pick<Requirement, "title" | "description" | "evidenceLevel" | "assumptions" | "uncertainties"> {
  return {
    title: `Draft requirement from "${input.signal.theme}"`,
    description: "Mock derivation — replace with Claude call grounded in linked sources.",
    evidenceLevel: input.sources.length >= 3 ? "strong" : input.sources.length === 2 ? "moderate" : "weak",
    assumptions: [],
    uncertainties: ["Generated by mock deriveRequirement(); not yet reviewed."],
  };
}

