"use client";

import { useEffect, useState, useCallback } from "react";
import Link from "next/link";
import { api, type Facets, type FeedbackPage } from "@/lib/api-client";

const FEEDBACK_TYPE_STYLE: Record<string, string> = {
  Likes: "text-emerald-300 border-emerald-800",
  Wants: "text-sky-300 border-sky-800",
  "Difficult to Use": "text-amber-300 border-amber-800",
  Defect: "text-red-300 border-red-800",
};

export default function EvidenceExplorerPage() {
  const [facets, setFacets] = useState<Facets | null>(null);
  const [data, setData] = useState<FeedbackPage | null>(null);
  const [vehicleCode, setVehicleCode] = useState("");
  const [component, setComponent] = useState("");
  const [feedbackType, setFeedbackType] = useState("");
  const [country, setCountry] = useState("");
  const [q, setQ] = useState("");
  const [page, setPage] = useState(1);
  const pageSize = 50;

  useEffect(() => {
    api.getFeedbackFacets().then(setFacets);
  }, []);

  const load = useCallback(() => {
    api.getFeedback({ vehicleCode, component, feedbackType, country, q, page, pageSize }).then(setData);
  }, [vehicleCode, component, feedbackType, country, q, page]);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    setPage(1);
  }, [vehicleCode, component, feedbackType, country, q]);

  const totalPages = data ? Math.max(1, Math.ceil(data.total / pageSize)) : 1;

  return (
    <main className="mx-auto min-h-screen max-w-7xl px-6 py-8">
      <div className="mb-6">
        <Link href="/" className="text-xs text-neutral-500 hover:text-neutral-300">← Landing page</Link>
        <h1 className="mt-1 text-xl font-bold text-neutral-50">Evidence Explorer</h1>
        <p className="text-sm text-neutral-500">
          Raw customer feedback behind every signal and requirement — filter, search, and drill down to the source record (US-1.3, US-8.1).
        </p>
      </div>

      {data?.noData && (
        <div className="border border-amber-800 bg-amber-950/30 p-4 text-sm text-amber-200">
          No real data ingested yet. Copy the datasets into <code className="font-mono">data-raw/</code> and run{" "}
          <code className="font-mono">npm run ingest</code> (see docs/DATA_SETUP.md).
        </div>
      )}

      {!data?.noData && (
        <>
          <div className="mb-4 grid grid-cols-2 gap-2 border border-neutral-800 bg-neutral-900/60 p-3 sm:grid-cols-5">
            <Select label="Vehicle" value={vehicleCode} onChange={setVehicleCode} options={facets?.vehicleCodes} />
            <Select label="Component" value={component} onChange={setComponent} options={facets?.components} />
            <Select label="Feedback type" value={feedbackType} onChange={setFeedbackType} options={facets?.feedbackTypes} />
            <Select label="Country" value={country} onChange={setCountry} options={facets?.countries} />
            <div>
              <label className="mb-1 block text-[10px] uppercase tracking-wide text-neutral-500">Search</label>
              <input
                value={q}
                onChange={(e) => setQ(e.target.value)}
                placeholder="text or VFC category…"
                className="w-full border border-neutral-700 bg-black/30 px-2 py-1.5 text-xs text-neutral-200 placeholder:text-neutral-600"
              />
            </div>
          </div>

          <div className="mb-2 flex items-center justify-between text-xs text-neutral-500">
            <span>
              {data?.total.toLocaleString() ?? "…"} rows matched
            </span>
            <div className="flex items-center gap-2">
              <button
                disabled={page <= 1}
                onClick={() => setPage((p) => p - 1)}
                className="border border-neutral-700 px-2 py-1 disabled:opacity-30"
              >
                ←
              </button>
              <span className="font-mono">
                {page} / {totalPages}
              </span>
              <button
                disabled={page >= totalPages}
                onClick={() => setPage((p) => p + 1)}
                className="border border-neutral-700 px-2 py-1 disabled:opacity-30"
              >
                →
              </button>
            </div>
          </div>

          <div className="overflow-x-auto border border-neutral-800">
            <table className="w-full border-collapse text-left text-xs">
              <thead>
                <tr className="border-b border-neutral-800 bg-neutral-900 text-[10px] uppercase tracking-wide text-neutral-500">
                  <th className="px-2 py-2 font-medium">ID</th>
                  <th className="px-2 py-2 font-medium">Vehicle</th>
                  <th className="px-2 py-2 font-medium">Country</th>
                  <th className="px-2 py-2 font-medium">Engine</th>
                  <th className="px-2 py-2 font-medium">Type</th>
                  <th className="px-2 py-2 font-medium">Category (VFC)</th>
                  <th className="px-2 py-2 font-medium">Feedback</th>
                </tr>
              </thead>
              <tbody>
                {data?.rows.map((r) => (
                  <tr key={r.id} className="border-b border-neutral-900 hover:bg-neutral-900/50">
                    <td className="px-2 py-2 font-mono text-neutral-600">{r.id}</td>
                    <td className="px-2 py-2 text-neutral-400">{r.vehicleCode}</td>
                    <td className="px-2 py-2 text-neutral-400">{r.country}</td>
                    <td className="px-2 py-2 text-neutral-500">{r.engineType}</td>
                    <td className="px-2 py-2">
                      {r.feedbackType ? (
                        <span className={`border px-1 py-0.5 text-[10px] ${FEEDBACK_TYPE_STYLE[r.feedbackType] ?? "border-neutral-700 text-neutral-400"}`}>
                          {r.feedbackType}
                        </span>
                      ) : (
                        <span className="text-neutral-700">—</span>
                      )}
                    </td>
                    <td className="px-2 py-2 text-neutral-500">{r.vfcLevel2 ?? "unclassified"}</td>
                    <td className="max-w-xl px-2 py-2 text-neutral-300">{r.text}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </main>
  );
}

function Select({
  label,
  value,
  onChange,
  options,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options?: { value: string; count: number }[];
}) {
  return (
    <div>
      <label className="mb-1 block text-[10px] uppercase tracking-wide text-neutral-500">{label}</label>
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full border border-neutral-700 bg-black/30 px-2 py-1.5 text-xs text-neutral-200"
      >
        <option value="">All</option>
        {options?.map((o) => (
          <option key={o.value} value={o.value}>
            {o.value} ({o.count.toLocaleString()})
          </option>
        ))}
      </select>
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { api } from "@/lib/api-client";
import type {
  Workflow,
  Requirement,
  AuditLogEntry,
  AISummary,
  StakeholderReview,
  Stakeholder,
  Signal,
  SourceRecord,
  VehicleComponent,
  Vehicle,
} from "@/lib/types";
import { PipelineStrip } from "@/components/PipelineStrip";
import { RequirementCard } from "@/components/RequirementCard";
import { AuditLogPanel } from "@/components/AuditLogPanel";
import { ReviewerRow } from "@/components/ReviewerRow";
import { EvidenceBadge } from "@/components/EvidenceBadge";

const SENTIMENT_DOT: Record<Signal["sentiment"], string> = {
  positive: "bg-emerald-500",
  negative: "bg-red-500",
  mixed: "bg-sky-500",
  neutral: "bg-neutral-600",
};

export default function WorkflowPage() {
  const params = useParams<{ componentId: string }>();
  const [workflow, setWorkflow] = useState<Workflow | null>(null);
  const [component, setComponent] = useState<VehicleComponent | null>(null);
  const [vehicle, setVehicle] = useState<Vehicle | null>(null);
  const [requirements, setRequirements] = useState<Requirement[]>([]);
  const [auditLog, setAuditLog] = useState<AuditLogEntry[]>([]);
  const [aiSummaries, setAISummaries] = useState<AISummary[]>([]);
  const [reviews, setReviews] = useState<StakeholderReview[]>([]);
  const [stakeholders, setStakeholders] = useState<Stakeholder[]>([]);
  const [signals, setSignals] = useState<Signal[]>([]);
  const [sources, setSources] = useState<SourceRecord[]>([]);
  const [selectedReqId, setSelectedReqId] = useState<string | null>(null);
  const [notFound, setNotFound] = useState(false);

  const refresh = useCallback(async () => {
    const [comp, wf] = await Promise.all([api.getComponent(params.componentId), api.getWorkflowByComponent(params.componentId)]);
    setComponent(comp);
    if (!wf) {
      setNotFound(true);
      return;
    }
    setWorkflow(wf);
    const [reqs, log, summaries, revs, shs, sig, veh] = await Promise.all([
      api.listRequirements(wf.id),
      api.getAuditLog(wf.id),
      api.getAISummaries(wf.id),
      api.listReviews(wf.id),
      api.listStakeholders(),
      api.getSignals(wf.id),
      api.getVehicle(wf.vehicleId),
    ]);
    setRequirements(reqs);
    setAuditLog(log);
    setAISummaries(summaries);
    setReviews(revs);
    setStakeholders(shs);
    setSignals([...sig.signals].sort((a, b) => b.frequency - a.frequency));
    setSources(sig.sources);
    setVehicle(veh);
  }, [params.componentId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  function onRequirementChanged(updated: Requirement) {
    setRequirements((rs) => rs.map((r) => (r.id === updated.id ? updated : r)));
    refresh(); // pick up new audit log / summary entries
  }

  if (notFound) {
    return (
      <main className="mx-auto max-w-2xl px-6 py-16 text-center">
        <p className="text-neutral-400">No workflow exists for this component yet.</p>
        <Link href="/" className="mt-4 inline-block text-sm text-sky-400 hover:text-sky-300">
          ← Back to landing page
        </Link>
      </main>
    );
  }

  if (!workflow) {
    return <main className="px-6 py-16 text-center text-neutral-500">Loading…</main>;
  }

  const decisionTrail = aiSummaries.find((s) => s.type === "decision_trail");
  const stakeholderOverview = aiSummaries.find((s) => s.type === "stakeholder_overview");
  const limitations = aiSummaries.find((s) => s.type === "limitations");

  const selectedReq = requirements.find((r) => r.id === selectedReqId) ?? requirements[0] ?? null;
  const selectedReviews = selectedReq ? reviews.filter((r) => r.requirementId === selectedReq.id) : [];
  const totalMentions = signals.reduce((a, s) => a + s.frequency, 0);

  return (
    <main className="mx-auto min-h-screen max-w-7xl px-6 py-8">
      <div className="mb-6 flex items-start justify-between">
        <div>
          <Link href="/" className="text-xs text-neutral-500 hover:text-neutral-300">← All components</Link>
          <h1 className="mt-1 text-xl font-bold text-neutral-50">
            {vehicle?.name ?? "…"} · {component?.label ?? "…"}
          </h1>
          <p className="font-mono text-xs text-neutral-500">
            market={workflow.market} · status={workflow.status} · {totalMentions.toLocaleString()} verbatims across {signals.length} themes
          </p>
        </div>
        <Link
          href={`/evidence?vehicleCode=${vehicle?.id?.replace("veh_", "").toUpperCase()}&component=${component?.key}`}
          className="shrink-0 border border-neutral-700 px-2.5 py-1.5 text-xs text-neutral-400 hover:border-neutral-500 hover:text-neutral-200"
        >
          Open Evidence Explorer →
        </Link>
      </div>

      <section className="mb-6 border border-neutral-800 bg-neutral-900/40 p-4">
        <PipelineStrip stages={workflow.stages} />
      </section>

      <div className="grid grid-cols-1 gap-5 lg:grid-cols-[1fr_340px]">
        <div className="space-y-5">
          {decisionTrail && (
            <section className="border-l-2 border-sky-600 bg-sky-950/20 p-3">
              <h2 className="text-[10px] font-semibold uppercase tracking-wide text-sky-400">AI summary · decision trail</h2>
              <p className="mt-1.5 text-xs leading-relaxed text-neutral-300">{decisionTrail.content}</p>
            </section>
          )}

          <section>
            <h2 className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-neutral-500">
              Requirements ({requirements.length})
            </h2>
            <div className="space-y-3">
              {requirements.map((req) => (
                <div key={req.id} onClick={() => setSelectedReqId(req.id)}>
                  <RequirementCard requirement={req} onChanged={onRequirementChanged} />
                </div>
              ))}
              {requirements.length === 0 && (
                <p className="text-sm text-neutral-500">No requirements derived yet.</p>
              )}
            </div>
          </section>

          {selectedReq && (
            <section className="border border-neutral-800 bg-neutral-900/40 p-3">
              <div className="mb-2 flex items-center justify-between">
                <h2 className="text-[11px] font-semibold uppercase tracking-wide text-neutral-500">
                  Stakeholder reviews — {selectedReq.title}
                </h2>
                <EvidenceBadge level={selectedReq.evidenceLevel} />
              </div>
              {stakeholderOverview && (
                <p className="mb-2 border-l-2 border-violet-600 bg-violet-950/20 p-2 text-[11px] text-violet-200">
                  <span className="font-semibold">AI overview: </span>
                  {stakeholderOverview.content}
                </p>
              )}
              <div className="space-y-2">
                {selectedReviews.map((rev) => (
                  <ReviewerRow key={rev.id} review={rev} stakeholder={stakeholders.find((s) => s.id === rev.stakeholderId)} />
                ))}
                {selectedReviews.length === 0 && (
                  <p className="text-xs text-neutral-500">No reviews requested for this requirement yet.</p>
                )}
              </div>
            </section>
          )}

          <section className="border border-neutral-800 bg-neutral-900/40 p-3">
            <h2 className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-neutral-500">
              Evidence &amp; sources — {signals.length} real feedback themes
            </h2>
            <div className="divide-y divide-neutral-800">
              {signals.map((sig) => (
                <details key={sig.id} className="group py-1.5">
                  <summary className="flex cursor-pointer items-center gap-2 text-xs text-neutral-300 hover:text-neutral-100">
                    <span className={`h-1.5 w-1.5 shrink-0 rounded-full ${SENTIMENT_DOT[sig.sentiment]}`} />
                    <span className="flex-1">{sig.theme}</span>
                    <span className="font-mono text-[10px] text-neutral-600">{sig.frequency}× · {sig.sentiment}</span>
                  </summary>
                  <ul className="mt-1.5 space-y-1 pl-5 text-[11px] text-neutral-500">
                    {sig.sourceIds
                      .map((id) => sources.find((s) => s.id === id))
                      .filter(Boolean)
                      .slice(0, 8)
                      .map((s) => (
                        <li key={s!.id}>
                          <span className="font-mono text-neutral-600">[{s!.datasetType}/{s!.reliability}{s!.country ? `/${s!.country}` : ""}]</span> {s!.excerpt}
                        </li>
                      ))}
                  </ul>
                </details>
              ))}
              {signals.length === 0 && <p className="text-xs text-neutral-600">No signals extracted yet.</p>}
            </div>
          </section>

          {limitations && (
            <section className="border-l-2 border-amber-600 bg-amber-950/20 p-3">
              <h2 className="text-[10px] font-semibold uppercase tracking-wide text-amber-400">Limitations</h2>
              <p className="mt-1.5 text-xs leading-relaxed text-neutral-300">{limitations.content}</p>
            </section>
          )}
        </div>

        <aside className="lg:sticky lg:top-8 lg:h-[calc(100vh-4rem)]">
          <h2 className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-neutral-500">
            Audit trail ({auditLog.length})
          </h2>
          <AuditLogPanel entries={auditLog} />
        </aside>
      </div>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { api } from "@/lib/api-client";
import type { Vehicle, VehicleComponent } from "@/lib/types";
import { CarHotspotViewer } from "@/components/CarHotspotViewer";

export default function LandingPage() {
  const router = useRouter();
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [vehicleId, setVehicleId] = useState<string | null>(null);
  const [components, setComponents] = useState<VehicleComponent[]>([]);
  const [creating, setCreating] = useState<VehicleComponent | null>(null);
  const [market, setMarket] = useState("Europe");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    api.listVehicles().then((vs) => {
      setVehicles(vs);
      if (vs[0]) setVehicleId(vs[0].id);
    });
  }, []);

  useEffect(() => {
    if (!vehicleId) return;
    api.listComponents(vehicleId).then(setComponents);
  }, [vehicleId]);

  const vehicle = vehicles.find((v) => v.id === vehicleId) ?? null;
  const activeCount = components.filter((c) => c.workflowId).length;

  async function handleSelect(component: VehicleComponent) {
    if (component.workflowId) {
      router.push(`/workflow/${component.id}`);
    } else {
      setMarket(vehicle?.markets[0] ?? "Europe");
      setCreating(component);
    }
  }

  async function confirmCreate() {
    if (!creating) return;
    setBusy(true);
    try {
      await api.createWorkflow(creating.id, market);
      router.push(`/workflow/${creating.id}`);
    } finally {
      setBusy(false);
    }
  }

  return (
    <main className="mx-auto flex min-h-screen max-w-6xl flex-col px-6 py-10">
      <header className="mb-6 flex flex-wrap items-start justify-between gap-4 border-b border-neutral-800 pb-6">
        <div>
          <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-bmw-blue">BMW Group · AI for Product Decision Making</p>
          <h1 className="mt-1 text-2xl font-bold text-neutral-50">Requirements Copilot</h1>
          <p className="mt-1 max-w-xl text-sm text-neutral-500">
            Click a component to open its requirements workflow, or start a new one. Blue dots have an active
            workflow; gray dots are untouched.
          </p>
        </div>
        <Link href="/evidence" className="shrink-0 border border-neutral-700 px-3 py-1.5 text-xs text-neutral-400 hover:border-neutral-500 hover:text-neutral-200">
          Evidence Explorer →
        </Link>
      </header>

      {vehicles.length > 0 && (
        <div className="mb-6 flex flex-wrap items-center gap-2">
          {vehicles.map((v) => (
            <button
              key={v.id}
              onClick={() => setVehicleId(v.id)}
              className={`border px-3 py-1.5 text-xs font-medium ${
                v.id === vehicleId
                  ? "border-bmw-blue bg-bmw-blue/10 text-sky-300"
                  : "border-neutral-700 text-neutral-500 hover:border-neutral-500 hover:text-neutral-300"
              }`}
            >
              {v.name}
            </button>
          ))}
        </div>
      )}

      {vehicle && (
        <p className="mb-4 font-mono text-xs text-neutral-500">
          {vehicle.generation} · markets: {vehicle.markets.join(", ")} · {activeCount}/{components.length} components have an active workflow
        </p>
      )}

      {components.length > 0 && <CarHotspotViewer components={components} onSelect={handleSelect} />}

      <div className="mt-8 grid w-full grid-cols-2 gap-2 sm:grid-cols-3">
        {components.map((c) => (
          <button
            key={c.id}
            onClick={() => handleSelect(c)}
            className="border border-neutral-800 bg-neutral-900/40 px-3 py-2.5 text-left text-sm hover:border-neutral-600 hover:bg-neutral-900"
          >
            <div className="font-medium text-neutral-200">{c.label}</div>
            <div className="mt-0.5 text-[11px] text-neutral-500">
              {c.workflowId ? "Workflow in progress →" : "No workflow yet — create one"}
            </div>
          </button>
        ))}
      </div>

      {creating && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4">
          <div className="w-full max-w-sm border border-neutral-700 bg-neutral-900 p-5 shadow-2xl">
            <h2 className="text-base font-semibold text-neutral-100">New workflow: {creating.label}</h2>
            <p className="mt-1 text-xs text-neutral-500">Choose the market scope for this requirements run.</p>
            <select
              value={market}
              onChange={(e) => setMarket(e.target.value)}
              className="mt-3 w-full border border-neutral-700 bg-black/30 px-3 py-2 text-sm text-neutral-200"
            >
              {(vehicle?.markets ?? ["Europe"]).map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
            <div className="mt-4 flex justify-end gap-2">
              <button
                onClick={() => setCreating(null)}
                className="px-3 py-1.5 text-sm text-neutral-400 hover:text-neutral-200"
              >
                Cancel
              </button>
              <button
                onClick={confirmCreate}
                disabled={busy}
                className="bg-bmw-blue px-3 py-1.5 text-sm font-semibold text-white hover:bg-sky-500 disabled:opacity-50"
              >
                {busy ? "Creating…" : "Create workflow"}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

