270	        "flex gap-3 px-4 py-3 text-[13px] leading-relaxed",
271	        isAssumption ? "bg-[#eef4fc] text-[#1d3d6b]" : "bg-amber-50 text-amber-900",
272	      )}
273	    >
274	      <span
275	        className={clsx(
276	          "mt-[3px] flex h-4 w-4 shrink-0 items-center justify-center rounded-full text-[10px] font-bold text-white",
277	          isAssumption ? "bg-bmw-blue" : "bg-amber-500",
278	        )}
279	      >
280	        {isAssumption ? "i" : "!"}
281	      </span>
282	      <span>
283	        <span className="mr-1.5 text-[10px] font-semibold uppercase tracking-[0.14em] opacity-70">{isAssumption ? "Assumption" : "Uncertainty"}</span>
284	        {text}
285	      </span>
286	    </div>
287	  );
288	}
289	
290	function computeLiveScore(requirement: Requirement, weights: Record<string, number>) {
291	  const totalWeight = requirement.scoreFactors.reduce((s, f) => s + (weights[f.key] ?? f.weight), 0) || 1;
292	  const weighted = requirement.scoreFactors.reduce(
293	    (s, f) => s + f.rawValue * (weights[f.key] ?? f.weight),
294	    0,
295	  );
296	  return weighted / totalWeight;
297	}
