"use client";

import Link from "next/link";
import clsx from "clsx";
import { BmwLogo } from "@/components/BmwLogo";

// Shared top nav for the light-themed pages (landing, workflow). Pulled out
// once two pages needed the identical header instead of copy-pasting it.
export function SiteHeader({ active }: { active: "vehicles" | "evidence" }) {
  return (
    <header className="sticky top-0 z-40 border-b border-neutral-200 bg-white/90 backdrop-blur">
      <div className="mx-auto flex h-16 max-w-[1440px] items-center justify-between px-4 sm:px-8">
        <Link href="/" className="flex items-center gap-3">
          <BmwLogo size={36} />
          <span className="hidden h-6 w-px bg-neutral-300 sm:block" />
          <span className="hidden text-[15px] font-semibold tracking-tight sm:block">Requirements Copilot</span>
        </Link>
        <nav className="flex items-center gap-1 text-sm">
          <Link
            href="/"
            className={clsx(
              "hidden px-3 py-5 font-medium md:block",
              active === "vehicles" ? "border-b-2 border-neutral-900 text-neutral-900" : "text-neutral-600 hover:text-neutral-900",
            )}
          >
            Vehicles
          </Link>
          <Link
            href="/evidence"
            className={clsx(
              "hidden px-3 py-5 font-medium md:block",
              active === "evidence" ? "border-b-2 border-neutral-900 text-neutral-900" : "text-neutral-600 hover:text-neutral-900",
            )}
          >
            Evidence Explorer
          </Link>
          <Link
            href="/evidence"
            className="ml-2 bg-bmw-blue px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-[#0653b6] md:hidden"
          >
            Evidence
          </Link>
        </nav>
      </div>
    </header>
  );
}

import clsx from "clsx";
import type { Requirement, EvidenceLevel } from "@/lib/types";

// Small shared building blocks for the (light-themed) workflow page and
// RequirementCard, so both describe the same visual language once instead
// of each hand-rolling chips/meters/rings.

export function Chip({ className, children }: { className?: string; children: React.ReactNode }) {
  return (
    <span className={clsx("px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.1em]", className)}>
      {children}
    </span>
  );
}

export const STATUS_CHIP: Record<Requirement["status"], string> = {
  proposed: "bg-neutral-100 text-neutral-700",
  approved: "bg-emerald-50 text-emerald-700",
  rejected: "bg-red-50 text-red-700",
  postponed: "bg-amber-50 text-amber-800",
  challenged: "bg-violet-50 text-violet-700",
};

// snake_case / kebab-case -> "space separated" (callers apply uppercase or
// sentence-case via CSS as needed — this just normalizes the separators).
export function humanize(value: string): string {
  return value.replace(/[_-]+/g, " ");
}

const EVIDENCE_STYLE: Record<EvidenceLevel, { dot: string; text: string; label: string }> = {
  strong: { dot: "bg-emerald-500", text: "text-emerald-700", label: "Strong evidence" },
  moderate: { dot: "bg-amber-500", text: "text-amber-700", label: "Moderate evidence" },
  weak: { dot: "bg-red-500", text: "text-red-700", label: "Weak evidence" },
};

export function EvidenceMeter({ level }: { level: EvidenceLevel }) {
  const s = EVIDENCE_STYLE[level];
  return (
    <span className={clsx("inline-flex items-center gap-1.5 text-[11px] font-medium", s.text)}>
      <span className={clsx("h-1.5 w-1.5 rounded-full", s.dot)} />
      {s.label}
    </span>
  );
}

// Compact circular score readout. `dirty` (unsaved weight changes pending)
// swaps the ring to a dashed outline so a PM never mistakes a live preview
// for the saved score.
export function ScoreRing({ score, dirty }: { score: number; dirty?: boolean }) {
  const pct = Math.max(0, Math.min(100, score));
  const r = 24;
  const c = 2 * Math.PI * r;
  const offset = c - (pct / 100) * c;
  return (
    <div className="relative flex h-[60px] w-[60px] shrink-0 items-center justify-center">
      <svg viewBox="0 0 60 60" className="h-full w-full -rotate-90">
        <circle cx="30" cy="30" r={r} fill="none" stroke="#e5e5e5" strokeWidth="4" />
        <circle
          cx="30"
          cy="30"
          r={r}
          fill="none"
          stroke={dirty ? "#9ca3af" : "#1c69d4"}
          strokeWidth="4"
          strokeDasharray={dirty ? "4 3" : c}
          strokeDashoffset={dirty ? 0 : offset}
          strokeLinecap="round"
        />
      </svg>
      <span className="absolute font-mono text-[14px] font-semibold tabular-nums text-neutral-900">{pct.toFixed(0)}</span>
    </div>
  );
}

export function SectionTitle({
  eyebrow,
  title,
  aside,
}: {
  eyebrow: string;
  title: string;
  aside?: React.ReactNode;
}) {
  return (
    <div className="mb-5 flex flex-wrap items-end justify-between gap-3 border-b border-neutral-200 pb-4">
      <div>
        <p className="text-[11px] font-semibold uppercase tracking-[0.22em] text-bmw-blue">{eyebrow}</p>
        <h2 className="mt-1 text-2xl font-light tracking-tight text-neutral-900">{title}</h2>
      </div>
      {aside}
    </div>
  );
}

"use client";

import type { Signal, SourceRecord } from "@/lib/types";

const SENTIMENT_DOT: Record<Signal["sentiment"], string> = {
  positive: "bg-emerald-500",
  negative: "bg-red-500",
  mixed: "bg-sky-500",
  neutral: "bg-neutral-400",
};

// Every real feedback theme behind this component's requirements, sorted
// by how often customers raised it. Expand one to see the actual source
// excerpts it was derived from — the evidence chain a requirement traces
// back to (US-8.1).
export function SignalBreakdown({ signals, sources }: { signals: Signal[]; sources: SourceRecord[] }) {
  if (signals.length === 0) {
    return <p className="text-[13px] text-neutral-500">No signals extracted yet.</p>;
  }
  return (
    <div className="divide-y divide-neutral-100">
      {signals.map((sig) => (
        <details key={sig.id} className="group py-3 first:pt-0 last:pb-0">
          <summary className="flex cursor-pointer list-none items-center gap-3 text-[13px] text-neutral-800 hover:text-neutral-950">
            <span className={`h-2 w-2 shrink-0 rounded-full ${SENTIMENT_DOT[sig.sentiment]}`} />
            <span className="flex-1 font-medium">{sig.theme}</span>
            <span className="font-mono text-[11px] text-neutral-400">
              {sig.frequency}× · {sig.sentiment}
            </span>
            <span className="text-neutral-300 transition-transform group-open:rotate-180">⌄</span>
          </summary>
          <ul className="mt-2 space-y-2 border-l-2 border-neutral-100 py-1 pl-5">
            {sig.sourceIds
              .map((id) => sources.find((s) => s.id === id))
              .filter((s): s is SourceRecord => Boolean(s))
              .slice(0, 8)
              .map((s) => (
                <li key={s.id} className="text-[12px] leading-relaxed text-neutral-500">
                  <span className="mr-1.5 font-mono text-[10px] uppercase tracking-wide text-neutral-400">
                    [{s.datasetType}/{s.reliability}
                    {s.country ? `/${s.country}` : ""}]
                  </span>
                  {s.excerpt}
                </li>
              ))}
          </ul>
        </details>
      ))}
    </div>
  );
}

