43	function scoreUnder(req: Requirement, weights: Record<string, number>): number {
44	  const totalWeight = req.scoreFactors.reduce((s, f) => s + (weights[f.key] ?? f.weight), 0) || 1;
45	  const weighted = req.scoreFactors.reduce((s, f) => s + f.rawValue * (weights[f.key] ?? f.weight), 0);
46	  return weighted / totalWeight;
47	}
