49	function ranksFor(requirements: Requirement[], scoreFn: (r: Requirement) => number): Map<string, number> {
50	  const sorted = [...requirements].sort((a, b) => scoreFn(b) - scoreFn(a));
51	  return new Map(sorted.map((r, i) => [r.id, i + 1]));
