1	"use client";
2	
3	import { useEffect, useState, useCallback } from "react";
4	import { useParams } from "next/navigation";
5	import { api } from "@/lib/api-client";
6	import type { Workflow, Requirement, StakeholderReview, Stakeholder, AISummary, VehicleComponent, Vehicle, CustomerStudyScore } from "@/lib/types";
7	import { EvidenceBadge } from "@/components/EvidenceBadge";
8	import { MetricBar } from "@/components/charts/MetricBar";
9	import { GroupedBarChart } from "@/components/charts/GroupedBarChart";
10	
11	export default function StakeholderPage() {
12	  const params = useParams<{ workflowId: string; stakeholderId: string }>();
13	  const [workflow, setWorkflow] = useState<Workflow | null>(null);
14	  const [component, setComponent] = useState<VehicleComponent | null>(null);
15	  const [vehicle, setVehicle] = useState<Vehicle | null>(null);
16	  const [requirements, setRequirements] = useState<Requirement[]>([]);
17	  const [reviews, setReviews] = useState<StakeholderReview[]>([]);
18	  const [stakeholder, setStakeholder] = useState<Stakeholder | null>(null);
19	  const [aiSummaries, setAISummaries] = useState<AISummary[]>([]);
20	  const [study, setStudy] = useState<CustomerStudyScore[]>([]);
21	  const [drafts, setDrafts] = useState<Record<string, string>>({});
22	  const [busyId, setBusyId] = useState<string | null>(null);
23	
24	  const refresh = useCallback(async () => {
25	    const [wf, shs] = await Promise.all([api.getWorkflow(params.workflowId), api.listStakeholders()]);
26	    setWorkflow(wf);
27	    setStakeholder(shs.find((s) => s.id === params.stakeholderId) ?? null);
28	    const [reqs, revs, summaries, comp, veh, cs] = await Promise.all([
29	      api.listRequirements(wf.id),
30	      api.listReviews(wf.id),
31	      api.getAISummaries(wf.id),
32	      api.getComponent(wf.componentId),
33	      api.getVehicle(wf.vehicleId),
34	      api.getCustomerStudy(wf.id),
35	    ]);
36	    setRequirements(reqs);
37	    setReviews(revs.filter((r) => r.stakeholderId === params.stakeholderId));
38	    setAISummaries(summaries);
39	    setComponent(comp);
40	    setVehicle(veh);
41	    setStudy(cs);
42	  }, [params.workflowId, params.stakeholderId]);
43	
44	  useEffect(() => {
45	    refresh();
46	  }, [refresh]);
47	
48	  async function submit(review: StakeholderReview, decision: "approve" | "reject") {
49	    setBusyId(review.id);
50	    try {
51	      await api.submitReview(review.id, decision, drafts[review.id] ?? review.expertOpinion);
52	      await refresh();
53	    } finally {
54	      setBusyId(null);
55	    }
56	  }
57	
58	  if (!workflow || !stakeholder) {
59	    return <main className="px-6 py-16 text-center text-neutral-500">Loading…</main>;
60	  }
61	
62	  const decisionTrail = aiSummaries.find((s) => s.type === "decision_trail");
63	  const studyByCategory = groupBy(study, (r) => r.category);
64	
65	  return (
66	    <main className="mx-auto min-h-screen max-w-3xl px-6 py-10">
67	      <header className="mb-6 border-b border-neutral-800 pb-5">
68	        <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-bmw-blue">Stakeholder review</p>
69	        <h1 className="mt-1 text-xl font-bold text-neutral-50">
70	          {vehicle?.name ?? "…"} · {component?.label ?? "…"} · {workflow.market}
71	        </h1>
72	        <p className="mt-1 text-xs text-neutral-500">
73	          Signed in as <span className="font-medium text-neutral-300">{stakeholder.name}</span> ({stakeholder.expertise.replace(/_/g, " ")})
74	        </p>
75	      </header>
76	
77	      {decisionTrail && (
78	        <section className="mb-5 border-l-2 border-sky-600 bg-sky-950/20 p-3">
79	          <h2 className="text-[10px] font-semibold uppercase tracking-wide text-sky-400">Summary so far</h2>
80	          <p className="mt-1.5 text-xs leading-relaxed text-neutral-300">{decisionTrail.content}</p>
81	        </section>
82	      )}
83	
84	      {Object.keys(studyByCategory).length > 0 && (
85	        <section className="mb-5 border border-neutral-800 bg-neutral-900/40 p-3">
86	          <h2 className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-neutral-500">
87	            Customer study — how we compare (0-10 mean, by model/region)
88	          </h2>
89	          <div className="grid gap-4 sm:grid-cols-2">
90	            {Object.entries(studyByCategory).map(([category, rows]) => (
91	              <div key={category}>
92	                <p className="mb-1 text-[11px] text-neutral-400">{category}</p>
93	                <GroupedBarChart
94	                  data={rows.map((r) => ({ label: `${r.model} ${r.region}`, value: r.mean, sub: r.methodology === "distribution_derived" ? "est." : undefined }))}
95	                  highlightLabel={vehicle?.name?.match(/\d/)?.[0]}
96	                />
97	              </div>
98	            ))}
99	          </div>
100	          <p className="mt-2 text-[10px] text-neutral-600">
