81	export function queryFeedback(args: Args): string {
82	  const vehicle = str(args.vehicle);
83	  const country = str(args.country)?.toUpperCase();
84	  const engine = str(args.engine_type);
85	  const type = str(args.feedback_type);
86	  const component = str(args.component);
87	  const theme = str(args.theme_contains)?.toLowerCase();
88	  const groupBy = str(args.group_by) ?? "theme";
89	  const limit = Math.min(Math.max(Number(args.limit) || 10, 1), 25);
90	
91	  const rows = loadFeedback().filter(
92	    (r) =>
93	      (!vehicle || r.vehicleCode === vehicle) &&
94	      (!country || r.country === country) &&
95	      (!engine || r.engineType === engine) &&
96	      (!type || r.feedbackType === type) &&
97	      (!component || r.component === component) &&
98	      (!theme || (r.vfcLevel2 ?? "").toLowerCase().includes(theme)),
99	  );
100	
101	  const keyOf: Record<string, (r: (typeof rows)[number]) => string | null> = {
102	    theme: (r) => r.vfcLevel2,
103	    component: (r) => r.component,
104	    country: (r) => r.country,
105	    engine_type: (r) => r.engineType,
106	    feedback_type: (r) => r.feedbackType || "untyped",
107	    vehicle: (r) => r.vehicleCode,
108	  };
109	  const key = keyOf[groupBy] ?? keyOf.theme;
110	
111	  const counts = new Map<string, number>();
112	  for (const r of rows) {
113	    const k = key(r);
114	    if (!k || k === "no_class_found") continue;
115	    counts.set(k, (counts.get(k) ?? 0) + 1);
116	  }
117	  const groups = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, limit).map(([k, count]) => ({ key: k, count }));
118	  return JSON.stringify({ matchingRows: rows.length, groupBy, groups });
119	}
