121	export function searchVerbatims(args: Args): string {
122	  const query = str(args.query)?.toLowerCase();
123	  if (!query) return JSON.stringify({ error: "query is required" });
124	  const vehicle = str(args.vehicle);
125	  const type = str(args.feedback_type);
126	  const hits: { id: string; vehicle: string; type: string | null; text: string }[] = [];
127	  let total = 0;
128	  for (const r of loadFeedback()) {
129	    if (vehicle && r.vehicleCode !== vehicle) continue;
130	    if (type && r.feedbackType !== type) continue;
131	    if (!r.text.toLowerCase().includes(query)) continue;
132	    total++;
133	    if (hits.length < 5) hits.push({ id: r.id, vehicle: r.vehicleCode, type: r.feedbackType, text: r.text.slice(0, 240) });
134	  }
135	  return JSON.stringify({ totalMatches: total, examples: hits });
136	}
