140	  const series = (Array.isArray(args.series) ? args.series : [])
141	    .map((s: unknown) => {
142	      const o = s as { name?: unknown; values?: unknown };
143	      const values = Array.isArray(o.values) ? o.values.map(Number).slice(0, categories.length) : [];
144	      return { name: String(o.name ?? ""), values };
145	    })
146	    .filter((s) => s.values.length === categories.length && s.values.every((v) => Number.isFinite(v)))
147	    .slice(0, 4);
148	  if (!categories.length || !series.length) return "Chart rejected: categories and series must be non-empty and the same length.";
149	  return {
