1	// Pingu's LLM loop: system prompt + data context + chat history, with a small
2	// tool-calling loop. Talks to the OpenAI chat completions endpoint over plain
3	// fetch (no SDK dependency). Server-side only — the key never reaches the client.
4	
5	import { buildContext } from "./context";
6	import { queryFeedback, searchVerbatims, TOOL_DEFINITIONS, validateChart } from "./tools";
7	import type { ChartSpec, ChatReply, ChatTurn } from "./types";
8	
9	const MAX_TOOL_ROUNDS = 4;
10	const MAX_HISTORY = 12;
11	const TIMEOUT_MS = 60_000;
12	
13	const SYSTEM_PROMPT = `You are Pingu, the penguin mascot and data assistant inside BMW Requirements Copilot. You help product managers explore customer feedback, sales volumes and customer-study scores for the BMW 1, 5 and 7 Series.
14	
15	Rules:
16	- Answer ONLY from the DATA below and from tool results. If the data does not cover the question, say so plainly and suggest what you can answer instead. Never invent numbers.
17	- Questions unrelated to this data: politely decline in one sentence and offer example questions.
18	- Use query_feedback for exact counts or filtered rankings (country, engine type, feedback type). Use search_verbatims to quote customers. The tables in DATA are pre-aggregated; prefer tools when a filter is involved.
19	- When asked for a graph/chart/plot (or when a comparison is clearly visual), call show_chart with numbers from the data, then add a one- or two-sentence takeaway. Do not describe the chart's every bar in text.
20	- Be concise and friendly: short paragraphs or bullets, real numbers, name the vehicle and market. Mention caveats (US study scores are derived; sample sizes; feedback is mostly US).
21	- The report is a customer-feedback tool, not an engineering spec: do not speculate about causes beyond what the verbatims say.
22	
23	DATA
24	`;
25	
26	interface ApiMessage {
27	  role: "system" | "user" | "assistant" | "tool";
28	  content: string | null;
29	  tool_calls?: { id: string; type: "function"; function: { name: string; arguments: string } }[];
30	  tool_call_id?: string;
31	}
32	
33	export class PinguConfigError extends Error {}
34	
35	export async function runPingu(history: ChatTurn[]): Promise<ChatReply> {
36	  const apiKey = process.env.OPENAI_API_KEY?.trim();
37	  if (!apiKey || apiKey === "your-key-here") {
38	    throw new PinguConfigError("OPENAI_API_KEY is not set. Add it to .env.local (see .env.example) and restart.");
39	  }
40	  const baseUrl = (process.env.OPENAI_BASE_URL?.trim() || "https://api.openai.com/v1").replace(/\/$/, "");
41	  const model = process.env.OPENAI_CHAT_MODEL?.trim() || "gpt-4.1-mini";
42	
43	  const messages: ApiMessage[] = [
44	    { role: "system", content: SYSTEM_PROMPT + buildContext() },
45	    ...history.slice(-MAX_HISTORY).map((t) => ({ role: t.role, content: t.content })),
46	  ];
47	  const charts: ChartSpec[] = [];
48	
49	  for (let round = 0; round <= MAX_TOOL_ROUNDS; round++) {
50	    const res = await fetch(`${baseUrl}/chat/completions`, {
51	      method: "POST",
52	      headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
53	      body: JSON.stringify({
54	        model,
55	        messages,
56	        tools: TOOL_DEFINITIONS,
57	        // After the last allowed round, force a plain-text answer.
58	        tool_choice: round === MAX_TOOL_ROUNDS ? "none" : "auto",
59	      }),
60	      signal: AbortSignal.timeout(TIMEOUT_MS),
61	    });
62	    if (!res.ok) {
63	      const detail = (await res.text()).slice(0, 300);
64	      throw new Error(`OpenAI request failed (${res.status}): ${detail}`);
65	    }
66	    const json = await res.json();
67	    const msg = json.choices?.[0]?.message as ApiMessage | undefined;
68	    if (!msg) throw new Error("OpenAI returned no message.");
69	
70	    if (!msg.tool_calls?.length) {
71	      return { reply: msg.content?.trim() || "Sorry, I came up empty. Try rephrasing?", charts };
72	    }
73	
74	    messages.push({ role: "assistant", content: msg.content ?? null, tool_calls: msg.tool_calls });
75	    for (const call of msg.tool_calls) {
76	      messages.push({ role: "tool", tool_call_id: call.id, content: execute(call.function.name, call.function.arguments, charts) });
77	    }
78	  }
79	  return { reply: "I got stuck on that one. Try a narrower question?", charts };
80	}
81	
82	function execute(name: string, rawArgs: string, charts: ChartSpec[]): string {
83	  let args: Record<string, unknown>;
84	  try {
85	    args = JSON.parse(rawArgs || "{}");
86	  } catch {
87	    return JSON.stringify({ error: "invalid JSON arguments" });
88	  }
89	  switch (name) {
90	    case "query_feedback":
91	      return queryFeedback(args);
92	    case "search_verbatims":
93	      return searchVerbatims(args);
94	    case "show_chart": {
95	      const chart = validateChart(args);
96	      if (typeof chart === "string") return JSON.stringify({ error: chart });
97	      charts.push(chart);
98	      return JSON.stringify({ ok: true, shown: chart.title });
99	    }
100	    default:
101	      return JSON.stringify({ error: `unknown tool ${name}` });
102	  }
103	}
